// How the achiever categories are shown. achievers-data.ts is generated by
// scripts/generate-achievers.mjs and overwritten on every run, so display
// choices live here instead: the order the categories appear in, and names
// with consistent capitalisation (the source mixes "K-CET TOPPERS" with
// "NEET Top Achievers"). Names match the header menu.

import { brochureStudents } from "./achievers-brochure";
import { type Achiever, type AchieverGroup, achieverGroups } from "./achievers-data";

const display: Record<string, { name: string; heading: string }> = {
  "jee-advanced": { name: "JEE Advanced", heading: "JEE Advanced Toppers" },
  "jee-mains": { name: "JEE Mains", heading: "JEE Mains Toppers" },
  neet: { name: "NEET", heading: "NEET Top Achievers" },
  "k-cet": { name: "K-CET", heading: "K-CET Toppers" },
};

// Results in exams the packages don't prepare for are left out — the site
// lists only KCET, NEET, JEE Main and JEE Advanced.
const hidden = new Set(["nstse"]);

const order = Object.keys(display);

/**
 * Where a published rank sorts, best first: ranks ascending ("Rank 57",
 * "AIR - 3084", a bare "309"), then percentiles and NEET scores descending
 * ("99.38%ile", "Score 697"), then anything without a number ("Qualified").
 */
function rankKey(rank: string): [number, number] {
  const percentile = rank.match(/(\d+(?:\.\d+)?)\s*%/);
  if (percentile) return [1, -Number(percentile[1])];
  const score = rank.match(/score\s*(\d+)/i);
  if (score) return [1, -Number(score[1])];
  const n = rank.match(/\d+/);
  if (n) return [0, Number(n[0])];
  return [2, 0];
}

function byRank(a: Achiever, b: Achiever) {
  const [ta, va] = rankKey(a.rank);
  const [tb, vb] = rankKey(b.rank);
  return ta - tb || va - vb;
}

/** The categories in display order, with display names. A category the
 *  generator adds later still shows, at the end, under its source name. */
export const achieverSections: AchieverGroup[] = achieverGroups
  .filter((g) => !hidden.has(g.slug))
  .sort((a, b) => {
    const ia = order.indexOf(a.slug);
    const ib = order.indexOf(b.slug);
    return (ia === -1 ? order.length : ia) - (ib === -1 ? order.length : ib);
  })
  .map((g) => ({
    ...g,
    ...(display[g.slug] ?? {}),
    // The source quotes carry stray quotation marks ("…satisfaction.” - …").
    quote: g.quote.replace(/[“”"]/g, "").trim(),
    // The brochure's lists replace the site's where it has one. Either way,
    // show the highest rank first; the sort is stable, so equal ranks keep
    // the source order.
    students: [...(brochureStudents[g.slug] ?? g.students)].sort(byRank),
  }));

export function sectionBySlug(slug: string) {
  return achieverSections.find((g) => g.slug === slug);
}

/**
 * Tidies a rank as the academy publishes it, without changing what it says:
 * a bare number becomes "Rank 309", and "AIR - 5942" / "State Rank - 4" lose
 * the stray dash.
 */
export function formatRank(rank: string) {
  const r = rank.trim();
  if (/^\d+$/.test(r)) return `Rank ${r}`;
  return r.replace(/\s*-\s*(?=\d)/g, " ").replace(/\s+/g, " ");
}

/** Every achiever listed on the site, across the categories shown. */
export const achieverCount = achieverSections.reduce((n, g) => n + g.students.length, 0);
